112			fprintf(stderr, "getclass() failed: %s\n", elf_errmsg(-1));
113			exit(EXIT_FAILURE);
114		} if ((id = elf_getident(e, NULL)) == NULL) {
115			fprintf(stderr, "getident() failed: %s\n", elf_errmsg(-1));
116			exit(EXIT_FAILURE);
117		} if (i != ELFCLASS32) {
118			fprintf(stderr, "This is a 64-bit ELF file, ZipCPU ELF files are all 32-bit\n");
