166			fprintf(stderr, "    %-20s 0x%jx\n", "p_offset", phdr.p_offset);
167			fprintf(stderr, "    %-20s 0x%jx\n", "p_vaddr",  phdr.p_vaddr);
168			fprintf(stderr, "    %-20s 0x%jx\n", "p_paddr",  phdr.p_paddr);
169			fprintf(stderr, "    %-20s 0x%jx\n", "p_filesz", phdr.p_filesz);
