186		ELFSECTION **r = sections = (ELFSECTION **)d;
187		current_offset = (n+1)*sizeof(ELFSECTION *);
188		current_section = 0;
189	
190		for(i=0; i<(int)n; i++) {
191			if (dbg) fprintf(stderr, "Working with &d[%d]\n", current_offset);
192			r[i] = (ELFSECTION *)(&d[current_offset]);
193	
194			if (gelf_getphdr(e, i, &phdr) != &phdr) {
195				fprintf(stderr, "getphdr() failed: %s\n", elf_errmsg(-1));
196				exit(EXIT_FAILURE);
197			}
198	
199			if (dbg) {
200			fprintf(stderr, "    %-20s 0x%jx\n", "p_offset", phdr.p_offset);
201			fprintf(stderr, "    %-20s 0x%jx\n", "p_vaddr",  phdr.p_vaddr);
202			fprintf(stderr, "    %-20s 0x%jx\n", "p_paddr",  phdr.p_paddr);
203			fprintf(stderr, "    %-20s 0x%jx\n", "p_filesz", phdr.p_filesz);
204			fprintf(stderr, "    %-20s 0x%jx\n", "p_memsz",  phdr.p_memsz);
205			fprintf(stderr, "    %-20s 0x%x [", "p_flags",  phdr.p_flags);
206	
207			if (phdr.p_flags & PF_X)	fprintf(stderr, " Execute");
208			if (phdr.p_flags & PF_R)	fprintf(stderr, " Read");
209			if (phdr.p_flags & PF_W)	fprintf(stderr, " Write");
210			fprintf(stderr, "]\n");
211	
212			fprintf(stderr, "    %-20s 0x%jx\n", "p_align", phdr.p_align);
213			}
214	
215			current_section++;
216	
217			r[i]->m_start = phdr.p_paddr;
218			r[i]->m_len   = phdr.p_filesz;
219			r[i]->m_vaddr = phdr.p_vaddr;
220	
221			current_offset += phdr.p_filesz + sizeof(ELFSECTION);
222	
223			// Now, let's read in our section ...
224			if (lseek(fd, phdr.p_offset, SEEK_SET) < 0) {
225				fprintf(stderr, "Could not seek to file position %08lx\n", (unsigned long)phdr.p_offset);
226				perror("O/S Err:");
227				exit(EXIT_FAILURE);
228			} if (phdr.p_filesz > phdr.p_memsz)
229				phdr.p_filesz = 0;
230			if (read(fd, r[i]->m_data, phdr.p_filesz) != (int)phdr.p_filesz) {
231				fprintf(stderr, "Didnt read entire section\n");
232				perror("O/S Err:");
233				exit(EXIT_FAILURE);
234			}
235	
236			/*
237			// Next, we need to byte swap it from big to little endian
238			for(unsigned j=0; j<r[i]->m_len; j++)
239				r[i]->m_data[j] = byteswap(r[i]->m_data[j]);
240			*/
241	
242			if (dbg) for(unsigned j=0; j<r[i]->m_len; j++)
243				fprintf(stderr, "ADR[%04x] = %02x\n", r[i]->m_start+j,
244					r[i]->m_data[j] & 0x0ff);
245		}
246	
247		r[i] = (ELFSECTION *)(&d[current_offset]);
248		r[current_section]->m_start = 0;
249		r[current_section]->m_len   = 0;
250	
251		elf_end(e);
252		close(fd);
253	}
