69	class	SIMDEV {
70	public:
71		virtual	uint32_t	lw(uint32_t addr) = 0;
72		virtual void	sw(uint32_t addr, uint32_t vl) = 0;
73	
74		virtual	uint32_t	lb(uint32_t addr) {
75			uint32_t v = lw(addr&-4);
76	
77			// fprintf(stderr, "\tLH(%08x) -> %08x", addr, v);
78			v >>= (8*(3-(addr&3)));
79			// fprintf(stderr, " -> %08x", v);
80			v &= 0x0ff;
81			// fprintf(stderr, " -> %02x\n", v);
82			return v;
83		}
84		virtual	uint32_t	lh(uint32_t addr) {
85			uint32_t v = lw(addr&-4);
86	
87			// fprintf(stderr, "\tLH(%08x) -> %08x", addr, v);
88			if ((addr&2)==0)
89				v >>= 16;
90			// fprintf(stderr, " -> %08x", v);
91			v &= 0x0ffff;
92			// fprintf(stderr, " -> %04x\n", v);
93			return v;
94		}
95	
96		virtual void sh(uint32_t addr, uint32_t vl) {
97			uint32_t v = (vl & 0x0ffff);
98			v = v | (v<<16);
99			sw(addr, v);
100		}
101	
102		virtual void sb(uint32_t addr, uint32_t vl) {
103			uint32_t v = (vl & 0x0ff);
104			v = v | (v<<16);
105			v = v | (v<<8);
106			sw(addr, v);
107		}
108	
109		virtual	bool	interrupt(void) { return false; };
110		virtual	void	tick(void) {};
111	
112		virtual	void	load(uint32_t addr, const char *buf, size_t ln) {}
113	};
