143	class	MEMDEV : public SIMDEV {
144	protected:
145		char	*m_mem;
146		bool	m_dbg;
147	public:
148		MEMDEV(int nbits) {
149			m_mem = new char[(1<<nbits)];
150			m_dbg = false;
151		}
152	
153		virtual	uint32_t	lw(uint32_t addr) {
154			unsigned char	a, b, c, d;
155			uint32_t	v;
156	
157			a = m_mem[addr];
158			b = m_mem[addr+1];
159			c = m_mem[addr+2];
160			d = m_mem[addr+3];
161			v = (a<<24)|(b<<16)|(c<<8)|d;
162	
163			if (m_dbg) fprintf(stderr,
164				"\tReading %08x -> %02x:%02x:%02x:%02x -> v=%08x\n", addr,
165				a, b, c, d, v);
166	
167			return v;
168		}
169	
170		virtual void sw(uint32_t addr, uint32_t vl) {
171			uint32_t maddr = addr & -4;
172			m_mem[(maddr)  ] = (vl >>24)&0x0ff;
173			m_mem[(maddr)+1] = (vl >>16)&0x0ff;
174			m_mem[(maddr)+2] = (vl >> 8)&0x0ff;
175			m_mem[(maddr)+3] = (vl     )&0x0ff;
176	
177			if (m_dbg)
178				fprintf(stderr,
179					"\tSW %08x <- %08x - %02x:%02x:%02x:%02x\n",
180					addr, vl, m_mem[(maddr)  ] & 0x0ff,
181					m_mem[(maddr)+1] & 0x0ff,
182					m_mem[(maddr)+2] & 0x0ff,
183					m_mem[(maddr)+3] & 0x0ff);
184		}
185	
186		virtual void sh(uint32_t addr, uint32_t vl) {
187			uint32_t maddr = addr & -2;
188			m_mem[(maddr)  ] = (vl >> 8)&0x0ff;
189			m_mem[(maddr)+1] = (vl     )&0x0ff;
190			if (m_dbg)
191				fprintf(stderr, "\tSH %08x <- %04x - %02x:%02x\n",
192					addr, vl & 0x0ffff, m_mem[(maddr)  ] & 0x0ff,
193					m_mem[(maddr)+1] & 0x0ff);
194		}
195	
196		virtual void sb(uint32_t addr, uint32_t vl) {
197			m_mem[addr] = vl;
198			if (m_dbg)
199				fprintf(stderr, "\tSB %08x <- %02x\n",
200					addr, vl & 0x0ff);
201		}
202	
203		void	load(uint32_t addr, const char *src, size_t n) {
204			memcpy(&m_mem[addr], src, n);
205		}
206	};
