441		void	ccodes(uint32_t newflags) {
442			m_r[14+rbase()] = (cc() & -16)|(newflags&0x0f);
443		}
444	
445		int	rbase(void) { return m_gie?16:0; }
446		bool	gie()		{ return m_gie; };
447		bool	locked()	{ return m_locked; };
448		bool	sleeping()	{
449			return (gie())&&(m_r[14+16]&CC_SLEEP)?true:false;
450		};
451		bool	sleep(bool nv)	{
452			if (nv) {
453				m_r[14   ] |= CC_SLEEP;
454				m_r[14+16] |= CC_SLEEP;
455			} else {
456				m_r[14   ] &= (~CC_SLEEP);
457				m_r[14+16] &= (~CC_SLEEP);
458			} return sleeping();
459		};
460		bool	halted()	{
461			return (!gie()) && (m_r[14]&CC_SLEEP);
462		};
463		uint32_t	cc()	{ return m_r[14+rbase()]|((m_gie)?CC_GIE:0); };
464		bool	fault()		{
465			if (cc() & (CC_PHASE|CC_ILL|CC_BREAK|CC_BUSERR|CC_DIVERR))
466				return true;
467			return false;
468		}
469		bool	gie(bool v)	{
470			m_jumped = (m_gie != v);
471			m_gie = v;
472			return v;
473		}
474		bool	jumped(void)	{ return m_jumped; };
475		void	pc_advance(bool pcgie) {
476			m_r[15+((pcgie)?16:0)] += 4;
477			m_r[15+((pcgie)?16:0)] &= -4;
478		} void	pc_advance(void) { pc_advance(gie()); }
479		uint32_t	pc(void)	{
480			return m_r[15+rbase()];
481		}
