497		void	siminsn(uint32_t insn) {
498			// fprintf(stderr, "SIM-INSN(0x%08x)\n", insn);
499			if ((insn & 0x0fffff)==0x00100) {
500				// SIM Exit(0)
501				exit(0);
502			} else if ((insn & 0x0ffff0)==0x00310) {
503				// SIM Exit(User-Reg)
504				int	rcode;
505				rcode = m_r[(insn&0x0f)+16] & 0x0ff;
506				exit(rcode);
507			} else if ((insn & 0x0ffff0)==0x00300) {
508				// SIM Exit(Reg)
509				int	rcode;
510				rcode = m_r[(insn&0x0f)+rbase()] & 0x0ff;
511				exit(rcode);
512			} else if ((insn & 0x0fff00)==0x00100) {
513				// SIM Exit(Imm)
514				int	rcode;
515				rcode = insn & 0x0ff;
516				exit(rcode);
517			} else if ((insn & 0x0fffff)==0x002ff) {
518				// Full/unconditional dump
519				fprintf(stderr, "SIM-DUMP\n");
520				dump();
521			} else if ((insn & 0x0ffff0)==0x00200) {
522				// Dump a register
523				int rid = (insn&0x0f)+rbase();
524				fprintf(stderr, "R[%2d] = 0x%08x\n", rid, m_r[rid]);
525			} else if ((insn & 0x0ffff0)==0x00210) {
526				// Dump a user register
527				int rid = (insn&0x0f);
528				fprintf(stderr, "uR[%2d] = 0x%08x\n", rid, m_r[rid+16]);
529			} else if ((insn & 0x0ffff0)==0x00230) {
530				// SOUT[User Reg]
531				int rid = (insn&0x0f)+16;
532				fprintf(stderr, "%c", m_r[rid]&0x0ff);
533			} else if ((insn & 0x0fffe0)==0x00220) {
534				// SOUT[User Reg]
535				int rid = (insn&0x0f)+rbase();
536				fprintf(stderr, "%c", m_r[rid]&0x0ff);
537			} else if ((insn & 0x0fff00)==0x00400) {
538				// SOUT[Imm]
539				fprintf(stderr, "%c", insn&0x0ff);
540			} else { // if ((insn & 0x0f7c00000)==0x77800000)
541				uint32_t	imm = insn & 0x03fffff;
542				// Simm instruction that we dont recognize
543				// if (imm)
544				fprintf(stderr, "SIM 0x%08x\n", imm);
545			}
546		}
547	
548		void	fullinsn(uint32_t insn) {
549			bool	wf, wb, fpu, noop, lock, wbreak, cmptst, mem,
550				sto, ldi, mov, div, execinsn;
551			bool	diverr, illegal;
552			uint32_t	av, bv, result, f, arg, brg, opc;
553			int32_t		imm;
554			int		rb, cnd;
555			const bool	dbg = false;
556	
557			m_icount ++ ;
558	
559			if (dbg) {
560				fprintf(stderr, "%8ld INSN(@0x%08x, %08x)", m_icount, pc(), insn);
561				if (m_mapf) {
562					// bool	dbg = pc() == 0x040003cc;
563					char	line[512], needle[512], *ptr = NULL,*lp;
564					sprintf(needle, "%08x", pc());
565					rewind(m_mapf);
566					while(NULL != (lp = fgets(line, sizeof(line), m_mapf))) {
567						while((*lp)&&(isspace(*lp)))
568							lp++;
569						if ((*lp != '0')||(tolower(*lp) == 'x'))
570							continue;
571						// if (dbg)fprintf(stderr, "\tMAP (%s?) %s\n", needle, lp);
572						if (NULL != (ptr = strstr(lp, needle))){
573							break;
574						}
575					} if (ptr) {
576						if (strlen(ptr) > 8)
577							ptr += 8;
578						while((*ptr)&&(isspace(*ptr)))
579							ptr++;
580						int ln = strlen(ptr);
581						while((ln > 0)&&(isspace(ptr[ln-1])))
582							ptr[--ln] = '\0';
583						fprintf(stderr, "\t%s", ptr);
584					} else if (0x7b400000 == (insn&0x7fffffff))
585						fprintf(stderr, "\treturn");
586				} else fprintf(stderr, "\tNO-MAPF");
587				fprintf(stderr, "\n");
588			}
589			m_jumped     = false;
590			m_advance_pc = true;
591			illegal      = false;
592			noop         = false;
593			lock         = false;
594			wbreak       = false;
595	
596			if (m_locked) {
597				m_lockcount--;
598				if (m_lockcount <= 0)
599					m_locked = false;
600			}
601	
602			m_r[14+rbase()]
603				&= ~(CC_ILL|CC_BREAK|CC_BUSERR|CC_DIVERR);
604	
605			opc = (insn >> 22) & 0x01f;
606			arg = (insn >> 27) & 0x0f;
607			brg = (insn >> 14) & 0x0f;
608	
609			cmptst=((opc&0x1e)==0x010);
610			mem = ((opc&0x1c) == 0x014)||((opc&0x1e) == 0x012);
611			sto = (mem)&&(opc&1);
612			fpu =(((opc&0x1c)==0x1c)		// Top four FPU ops
613					||((opc&0x1e)==0x1a));	// Bottom two FPU ops
614			div =((opc&0x1e)==0x0e);
615			ldi =((opc&0x1e)==0x18);
616			mov =((opc&0x1f)==0x0d);
617	
618			if (ldi)	imm = sbits(insn, 23);
619			else if (mov)	imm = sbits(insn, 13);
620			else if (insn & 0x040000)
621					imm = sbits(insn, 14);
622			else		imm = sbits(insn, 18);
623	
624			// Do we read the B register?
625			rb = (mov)||(((insn>>18)&1)&&(!ldi));
626	
627			// WriteBack
628			wb = (!cmptst)&&(!sto);
629	
630			// Do we write flags back?
631			wf = true;
632			if (ldi)	wf = false;
633			if (mov)	wf = false;
634			if (mem)	wf = false;
635			if (opc==0x08)	wf = false;	// BREV
636			if (opc==0x09)	wf = false;	// LDILO
637			if ((!cmptst)&&((arg & 0x0e)==0x0e)) // Writes to CC or PC
638				wf = false;		// dont set the flags.
639	
640			cnd = (ldi) ? 0 : ((insn >> 19) & 7);
641	
642			if (fpu & ((arg&0x0e)==0x0e)) {
643				fpu = false;
644				noop  = ((opc&0x1e) == 0x1e);
645				lock  = ((opc&0x1f) == 0x1d);
646				wbreak = ((opc&0x1f) == 0x1c);
647				illegal = !(noop|lock|wbreak);
648				wb     = false;
649				wf     = false;
650				cnd    = 0;
651			} else if (div & ((arg&0x0e)==0x0e)) {
652				illegal = true;
653			}
654	
655			if (cnd != 0) {
656				if (!cmptst)
657					wf = false;
658				int	ccodes = cc() & 0x0f;
659				switch(cnd) {
660				case 1: execinsn =  (ccodes & CC_Z); break;
661				case 2: execinsn =  (ccodes & CC_N); break;
662				case 3: execinsn =  (ccodes & CC_C); break;
663				case 4: execinsn =  (ccodes & CC_V); break;
664				case 5: execinsn = ((ccodes & CC_Z)==0); break;	// NZ
665				case 6: execinsn = ((ccodes & CC_N)==0); break;	// GE
666				case 7: execinsn = ((ccodes & CC_C)==0); break;	// NC
667				default:	execinsn = true;	break;
668				}
669			} else
670				execinsn = true;
671	
672			if ((mov)&&(!gie())) {
673				// Supervisor can read all registers
674				arg |= (insn&0x40000)?0x10:0;
675				brg |= (insn&0x02000)?0x10:0;
676			} else {
677				arg |= (gie())?0x10:0;
678				brg |= (gie())?0x10:0;
679			}
680			result = 0;
681	
682			bv = imm;
683			if (rb) {
684				if ((brg&0x0f)==15) { // PC 
685					bv = (imm << 2) + m_r[brg];
686					if (gie()) {
687						if (brg & 0x010)
688							bv += 4;
689					} else if ((brg & 0x10)==0)
690						bv += 4;
691				} else
692					bv += m_r[brg];
693			}
694			av = m_r[arg];
695			if ((int)arg == 15 + rbase())
696				av += 4;
697	
698			if (execinsn) {
699				f = 0;	// Resulting flags
700				if (fpu) {
701					float	fva, fvb, fvr;
702					fva = *(float *)&av;
703					fvb = *(float *)&bv;
704	
705					switch(opc) {
706					case 26: fvr = fva + fvb;	break;
707					case 27: fvr = fva - fvb;	break;
708					case 28: fvr = fva * fvb;	break;
709					case 29: fvr = fva / fvb;	break;
710					case 30: fvr = (float)bv;	break;
711					case 31: result = (int)fvb;	break;
712					default: illegal = true;
713					} if (opc != 31)
714						result = *(uint32_t *)&fvr;
715					if (result == 0)
716						f = CC_Z;
717					if (opc == 31) {
718						if (result & 0x80000000)
719							f |= CC_N;
720					} else if (fvr < 0.0)
721						f |= CC_N;
722				} else if (noop) {
723					if (insn != 0x7fc00000)
724						siminsn(insn);
725				} else if (wbreak) {
726					wf = wb = false;
727					m_advance_pc = false;
728					if (gie()) {
729						m_r[16+14] &= CC_BREAK;
730						gie(false);
731					} else {
732						fprintf(stderr, "BREAK!\n");
733						dump();
734						exit(EXIT_FAILURE);
735					}
736				} else if (lock) {
737					m_locked = true;
738					m_lockcount = 3;
739				} else {
740					uint32_t	presign = (av>>31)&1, nsgn;
741					switch(opc) {
742					case  0: case 16: { // SUB, or CMP
743						result = av - bv;
744						if (av < bv)
745							f |= CC_C;
746						nsgn = (result >> 31)&1;
747						if (presign != nsgn)
748							f |= CC_V;
749						} break;
750					case  1: case 17: result = bv & av; break;//AND or TST
751					case  2: { // ADD
752						result = bv + av;
753						if (result<(uint64_t)bv+(uint64_t)av)
754							f |= CC_C;
755						nsgn = (result >> 31)&1;
756						if (presign != nsgn)
757							f |= CC_V;
758						} break;
759					case  3: result = bv | av; break; // OR
760					case  4: result = bv ^ av; break; // XOR
761					case  5: { // LSR
762						uint32_t nsgn;
763						if (bv >= 32)
764							result = 0;
765						else
766							result = ((uint32_t)av >> bv);
767						nsgn = (result >> 31)&1;
768						if (presign != nsgn)
769							f |= CC_V;
770	
771						if ((bv !=0)&&(bv<33)&&(av&(1<<(bv-1))))
772							f |= CC_C;
773						} break;
774					case  6: { // LSL
775						uint32_t nsgn;
776						if (bv >= 32)
777							result = 0;
778						else
779							result = av << bv;
780						nsgn = (result >> 31)&1;
781						if (presign != nsgn)
782							f |= CC_V;
783						if((bv !=0)&&(bv<33)&&(av&(1<<(33-bv))))
784							f |= CC_C;
785						} break;
786					case  7: { // ASR
787						if ((bv >= 32)&&(av & 0x80000000))
788							result = -1;
789						else if (bv >= 32)
790							result = 0;
791						else
792							result = ((int)av >> bv);
793	
794						if (av & 0x80000000) {
795							// Signed carry
796							if (bv >= 31)
797								f |= CC_C;
798							else if((bv != 0)
799								&&(av&(1<<(33-bv))))
800								f |= CC_C;
801						} else {
802							// Unsigned carry
803							if((bv !=0)&&(bv<32)
804								&&(av&(1<<(33-bv))))
805								f |= CC_C;
806						}
807						} break;
808					case  8: result = bitreverse(bv);	break; // BREV
809					case  9: result = (av&0xffff0000)|(bv&0x0ffff);	break; // LDILO
810					case 10: { // MPYUHI
811						uint64_t ulv = av * bv;
812						result = (ulv >> 32);
813						} break;
814					case 11: { // MPYSHI
815						int64_t	lv = av * bv;
816						result = (lv >> 32);
817						} break;
818					case 12: { // MPY
819						int64_t ulv = av * bv;
820						// bool	sn = (av<0)^(bv<0);
821						result = (int32_t)(ulv & 0x0ffffffff);
822						//if (((result&0x80000000)?1:0)
823						//		^ ((sn)?1:0))
824						//	f |= CC_V;
825						} break;
826					case 13: result = bv;		break; // MOV
827					case 14: { // DIVU
828						if (bv == 0)
829							diverr = true;
830						else
831							result = (uint32_t)av
832								/ (uint32_t)bv;
833						} break;
834					case 15: { // DIVS
835						if (bv == 0)
836							diverr = true;
837						else
838							result =(int32_t)av/(int32_t)bv;
839						} break;
840					// case 16: result = av - bv;	break;
841					// case 17: result = av & bv;	break;
842					case 18: result = m_bus->lw(bv);
843						break;// LW
844					case 19:
845						m_bus->sw(bv, av);	break;// SW
846					case 20: result = m_bus->lh(bv);break;// LH
847					case 21: m_bus->sh(bv, av);	break;// SH
848					case 22: result = m_bus->lb(bv);break;// LB
849					case 23: m_bus->sb(bv, av);	break;// SB
850					case 24: result = bv;		break;// LDI
851					case 25: result = bv;		break;// LDI
852					default: illegal = true;
853					}
854					if (result == 0)
855						f |= CC_Z;
856					if (result & 0x80000000)
857						f |= CC_N;
858				}
859	
860				if (illegal) {
861					if (gie()) {
862						m_r[16+14] |= CC_ILL;
863						gie(false);
864						m_jumped = true;
865						m_advance_pc = false;
866					} else {
867						m_r[14] |= CC_ILL;
868						fprintf(stderr, "ILLegal Instruction Exception\n");
869						dump();
870						exit(EXIT_FAILURE);
871					}
872				} else if ((mem)&&(m_bus->error())) {
873					if (gie()) {
874						m_r[16+14] |= CC_BUSERR;
875						gie(false);
876						m_jumped = true;
877						m_advance_pc = false;
878					} else {
879						m_r[14] |= CC_BUSERR;
880						fprintf(stderr, "BUS ERR\n");
881						dump();
882						exit(EXIT_FAILURE);
883					}
884				} else if ((div)&&(diverr)) {
885					if (gie()) {
886						m_r[16+14] |= CC_DIVERR;
887						gie(false);
888						m_jumped = true;
889						m_advance_pc = false;
890					} else {
891						m_r[14] |= CC_DIVERR;
892						fprintf(stderr, "DIV ERR: division by zero\n");
893						dump();
894						exit(EXIT_FAILURE);
895					}
896				} if (wf)
897					ccodes(f);
898				if (wb) {
899					if (arg == (uint32_t)(15+rbase()))
900						m_jumped = true;
901					else if (arg == (uint32_t)(14+rbase())) {
902						if (gie()) {
903							if ((result & CC_GIE)==0) {
904								result |= CC_TRAP;
905								result &= (~(CC_SLEEP
906								|CC_ILL
907								|CC_BREAK
908								|CC_BUSERR
909								|CC_DIVERR
910								|CC_FPUERR
911								|CC_STEP
912								|CC_SLEEP));
913							}
914						} else if (result & CC_GIE) {
915							// Returning to userspace
916							m_r[16+14] &= (~(CC_ILL
917								|CC_BREAK
918								|CC_BUSERR
919								|CC_DIVERR
920								|CC_FPUERR));
921						}
922					}
923					if (dbg) fprintf(stderr,
924						"\tREG[%02x] = %08x\n", arg, result);
925					m_r[arg] = result;
926					if ((int)arg == 15+rbase())
927						m_advance_pc = false;
928					if (((int)arg==14+rbase())&&(((m_gie)?1:0)^((result&CC_GIE)?1:0))) {
929						gie((result&CC_GIE)?true:false);
930						// Prevent us from advancing the PC
931						m_jumped = true;
932						// m_advance_pc = true;
933					}
934					// Some CC bits are constant.  Keep them that
935					// way.
936					m_r[14   ] &= (~CC_GIE);
937					m_r[14+16] |= ( CC_GIE);
938					m_r[15   ] &= -4;
939					m_r[15+16] &= -4;
940				}
941			}
942		}
943	
944		void	cisinsn(uint16_t insn) {
945			uint32_t	imm;
946			int		dr, br, cisop, fullop;
947	
948			cisop = (insn >> 8) & 0x07;
949			switch(cisop) {
950			case 0: fullop =  0; break; // SUB
951			case 1: fullop =  1; break; // AND
952			case 2: fullop =  2; break; // ADD
953			case 3: fullop = 16; break; // CMP
954			case 4: fullop = 18; break; // LW
955			case 5: fullop = 19; break; // SW
956			case 6: fullop = 24; break; // LDI
957			case 7: fullop = 13; break; // MOV
958			}
959	
960			dr = (insn>>11) & 0x0f;
961	
962			if (fullop == 24) {
963				// LDI
964				imm = sbits(insn, 8) & 0x07fffff;
965				fullinsn(0x80000000 | (dr<<27) | (fullop<<22) | imm);
966			} else if (fullop == 13) {
967				// MOV
968				br = (insn >> 3) & 0x0f;
969				imm = sbits(insn, 3) & 0x01fff;
970				fullinsn(0x80000000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
971			} else if (insn & 0x80) {
972				// Uses a breg
973				br = (insn >> 3) & 0x0f;
974				imm = sbits(insn, 3) & 0x3fff;
975				fullinsn(0x80040000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
976			} else if ((fullop == 18)||(fullop == 19)) {
977				// Load or store, breg is assumed to be SP
978	// 0x04844000
979				br = 13;
980				imm = sbits(insn, 7) & 0x3fff;
981				fullinsn(0x80040000 | (dr << 27) | (fullop<<22) | (br<<14) | imm);
982			} else {
983				imm = sbits(insn, 7) & 0x03ffff;
984				fullinsn(0x80000000 | (dr << 27) | (fullop<<22) | imm);
985			}
986		}
987	
988		void	execute(uint32_t insn) {
989			/// fprintf(stderr, "EXEC-INSN(@0x%08x - %08x)\n", pc(), insn);
990			bool	igie = gie();
991			if (insn & 0x80000000) {
992				int		ibase = rbase();
993				cisinsn((insn>>16) & 0x0ffff);
994				if (m_advance_pc)
995					m_r[14+ibase] |= (CC_PHASE);
996				if ((!m_jumped)&&(igie == gie())) {
997					cisinsn(insn & 0x0ffff);
998					m_r[14+ibase] &= ~(CC_PHASE);
999				} if (m_advance_pc)
1000					pc_advance(igie);
1001				m_jumped = false;
1002			} else {
1003				m_r[14+rbase()] &= ~(CC_PHASE);
1004				fullinsn(insn);
1005	
1006				if (m_advance_pc)
1007					pc_advance(igie);
1008	
1009				if ((gie())&&(cc() & CC_STEP))
1010					gie(false);
1011			}
1012		}
1013	};
